original_problem.constraints:
1 ≤ N ≤ 10^{5} 
-10^{4}  ≤ a[i] ≤ 10^{4}

expected time complexity: O(N * Log(N))
expected auxiliary space: O(1)

original_problem.standard_solution_code:
class Solution:

	def ValidPair(self, a, n):
		a.sort()
		count = 0
		i = 0
		j = n - 1
		while i < j:
			if a[i] + a[j] > 0:
				count += j - i
				j -= 1
			else:
				i += 1
		return count
